(async function(){
    for (let i=0;i<15;i++){ if (document.readyState==='complete') break; await new Promise(r=>setTimeout(r,1500)); }
    const d = document;
    const out = { href: location.href, title: d.title, ready: d.readyState };
    out.fields = [];
    d.querySelectorAll('form').forEach(f => {
      const fid = { id: f.id || null, action: f.action, method: f.method, inputs: [] };
      f.querySelectorAll('input, select, textarea, button').forEach(el => {
        fid.inputs.push({
          tag: el.tagName, type: el.type || null, name: el.name || null, id: el.id || null,
          cls: String(el.className||'').slice(0,60),
          value: el.type==='checkbox'||el.type==='radio' ? String(el.checked) : (el.value || '').slice(0,80),
          options: el.tagName==='SELECT' ? Array.from(el.options).map(o=>o.value+':'+o.textContent.trim()).slice(0,60) : undefined,
          placeholder: el.placeholder || undefined,
          max: el.maxLength || undefined
        });
      });
      out.fields.push(fid);
    });
    out.standalone = [];
    d.querySelectorAll('input,select,textarea').forEach(el => {
      if (el.form) return;
      out.standalone.push({ tag: el.tagName, type: el.type||null, name: el.name||null, id: el.id||null });
    });
    out.sections = [];
    d.querySelectorAll('h1,h2,h3,h4,.title,.sec-title,.section-title,legend').forEach(el => {
      const t = (el.textContent||'').trim().replace(/\s+/g,' ').slice(0,50);
      if (t) out.sections.push({ text: t, tag: el.tagName, cls: String(el.className||'').slice(0,50) });
    });
    out.radioGroups = {};
    d.querySelectorAll('input[type=radio]').forEach(el => {
      const g = el.name || 'ungrouped';
      if (!out.radioGroups[g]) out.radioGroups[g] = [];
      out.radioGroups[g].push({ value: el.value, checked: el.checked, label: (el.parentElement ? (el.parentElement.textContent||'').trim().replace(/\s+/g,' ').slice(0,30) : '') });
    });
    out.checkboxGroups = {};
    d.querySelectorAll('input[type=checkbox]').forEach(el => {
      const g = el.name || 'ungrouped';
      if (!out.checkboxGroups[g]) out.checkboxGroups[g] = [];
      out.checkboxGroups[g].push({ value: el.value, checked: el.checked, label: (el.parentElement ? (el.parentElement.textContent||'').trim().replace(/\s+/g,' ').slice(0,30) : '') });
    });
    return JSON.stringify(out);
  })()
